const chamada = [
  { nome: 'Lia', presente: true },
  { nome: 'Caio', presente: false },
  { nome: 'Rui', presente: true },
  { nome: 'Nara', presente: false },
  { nome: 'Gabi', presente: true },
];

const faltas = [];
for (const aluno of chamada) {
  if (!aluno.presente) {
    faltas.push(aluno.nome);
  }
}

console.log(faltas);
console.log(`Faltaram ${faltas.length} alunos`);

