exercises.solution:
function montarTreino(inicio, aumento, semanas, limite) {
  const treino = [];
  for (let i = 0; i < semanas; i++) {
    const minutos = inicio + aumento * i;
    if (minutos > limite) {
      treino.push(limite);
    } else {
      treino.push(minutos);
    }
  }
  return treino;
}

const plano = montarTreino(20, 5, 6, 35);
console.log(plano);

for (let i = 0; i < plano.length; i++) {
  console.log(`Semana ${i + 1}: ${plano[i]} minutos`);
}

